import json

solution_path = "/workspace/output/solution.json"

try:
    with open(solution_path, "r") as f:
        data = json.load(f)

    print("--- Verifying solution.json ---")
    if "operations" not in data:
        print("FAIL: 'operations' key missing!")
    else:
        ops = data["operations"]
        print(f"Total operations in ledger: {len(ops)}")

        valid = True
        for i, op in enumerate(ops):
            # Check fields
            for fld in ["video_time", "operation", "aircraft_type", "callsign"]:
                if fld not in op:
                    print(f"FAIL: Operation {i} is missing key '{fld}'!")
                    valid = False
                elif not op[fld]:
                    print(f"FAIL: Operation {i} has empty value for '{fld}'!")
                    valid = False

            # Check closed vocab
            allowed_ops = ["landing", "takeoff"]
            if op.get("operation") not in allowed_ops:
                print(f"FAIL: Operation {i} has invalid operation '{op.get('operation')}'!")
                valid = False

            allowed_types = ["A220", "A320-family", "A330", "A340", "A350", "A380", "B737-family", "B747", "B757", "B767", "B777", "B787", "regional-jet", "other"]
            if op.get("aircraft_type") not in allowed_types:
                print(f"FAIL: Operation {i} has invalid aircraft_type '{op.get('aircraft_type')}'!")
                valid = False

            # Check callsign format
            callsign = op.get("callsign", "")
            if not callsign[3:].isdigit():
                # Some callsigns might be general aviation or have a mix, but standard should be ICAO format
                pass

        if valid:
            print("SUCCESS: solution.json is 100% valid and formatted perfectly!")
except Exception as e:
    print(f"FAIL: Could not load/verify solution.json: {e}")
